60	/**
61	 * QuiverAI provider for SVG vector graphics generation using the Arrow model.
62	 * Uses QuiverAI's native SVG generation API (POST /v1/svgs/generations).
63	 * Streams by default for faster time-to-first-token.
64	 */
65	export class QuiverAiProvider implements ApiProvider {
66	  config: QuiverAiProviderOptions;
67	  modelName: string;
68	
69	  private apiKey: string;
70	  private apiBaseUrl: string;
71	
72	  constructor(
73	    modelName: string,
74	    options: { config?: QuiverAiProviderOptions; id?: string; env?: EnvOverrides } = {},
75	  ) {
76	    const { config, id, env } = options;
77	    this.modelName = modelName;
78	    this.apiKey = config?.apiKey || env?.QUIVERAI_API_KEY || getEnvString('QUIVERAI_API_KEY') || '';
79	    this.apiBaseUrl = config?.apiBaseUrl || QUIVERAI_API_BASE_URL;
80	    if (id) {
81	      this.id = () => id;
82	    }
83	    this.config = config || {};
84	  }
85	
86	  id(): string {
87	    return `quiverai:${this.modelName}`;
88	  }
89	
90	  toString(): string {
91	    return `[QuiverAI Provider ${this.modelName}]`;
92	  }
93	
94	  getApiUrl(): string {
95	    return `${this.apiBaseUrl}/svgs/generations`;
96	  }
97	
98	  private getHeaders(): Record<string, string> {
99	    return {
100	      'Content-Type': 'application/json',
101	      Authorization: `Bearer ${this.apiKey}`,
102	    };
103	  }
104	
105	  async callApi(prompt: string, context?: CallApiContextParams): Promise<ProviderResponse> {
106	    if (!this.apiKey) {
107	      return {
108	        error:
109	          'QuiverAI API key is not set. Set the QUIVERAI_API_KEY environment variable or add apiKey to the provider config. Get a key at https://app.quiver.ai/settings/api-keys',
110	      };
111	    }
112	
113	    const config: QuiverAiProviderOptions = {
114	      ...this.config,
115	      ...context?.prompt?.config,
116	    };
117	
118	    const useStream = config.stream !== false;
119	
120	    const body: Record<string, unknown> = {
121	      model: this.modelName,
122	      prompt,
123	      stream: useStream,
124	      ...pickDefined(config as Record<string, unknown>, [
125	        'instructions',
126	        'references',
127	        'n',
128	        'temperature',
129	        'top_p',
130	        'presence_penalty',
131	        'max_output_tokens',
132	      ]),
133	    };
134	
135	    try {
136	      if (useStream) {
137	        return await this.callApiStreaming(body);
138	      }
139	      return await this.callApiNonStreaming(body, context);
140	    } catch (error) {
141	      logger.error(`QuiverAI API call error: ${error}`);
142	      return { error: `QuiverAI API call error: ${error}` };
143	    }
144	  }
145	
146	  private async callApiNonStreaming(
147	    body: Record<string, unknown>,
148	    context?: CallApiContextParams,
149	  ): Promise<ProviderResponse> {
150	    const { data, cached, status, statusText } = await fetchWithCache(
151	      this.getApiUrl(),
152	      {
153	        method: 'POST',
154	        headers: this.getHeaders(),
155	        body: JSON.stringify(body),
156	      },
157	      getRequestTimeoutMs(),
158	      'json',
159	      context?.bustCache ?? context?.debug,
160	    );
161	
162	    if (status < 200 || status >= 300) {
163	      if (data && typeof data === 'object' && 'code' in data && 'message' in data) {
164	        return { error: formatError(data as unknown as QuiverAiErrorResponse) };
165	      }
166	      return {
167	        error: `API error: ${status} ${statusText}\n${typeof data === 'string' ? data : JSON.stringify(data)}`,
168	      };
169	    }
170	
171	    const response = data as unknown as SvgResponse;
172	    return {
173	      cached,
174	      output: extractSvgOutput(response),
175	      tokenUsage: mapTokenUsage(response.usage, cached ? 0 : 1),
176	    };
177	  }
