179	  private async callApiStreaming(body: Record<string, unknown>): Promise<ProviderResponse> {
180	    const maxRetries = 3;
181	    let lastResp: Response | undefined;
182	
183	    for (let attempt = 0; attempt <= maxRetries; attempt++) {
184	      const controller = new AbortController();
185	      const timeout = setTimeout(() => controller.abort(), getRequestTimeoutMs());
186	      let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
187	
188	      try {
189	        lastResp = await fetchWithProxy(this.getApiUrl(), {
190	          method: 'POST',
191	          headers: this.getHeaders(),
192	          body: JSON.stringify(body),
193	          signal: controller.signal,
194	        });
195	
196	        // Retry on 429 rate limit. Transient 5xx (502/503/504/524) are handled by
197	        // fetchWithProxy's built-in retry which checks statusText to distinguish
198	        // permanent from transient failures before retrying.
199	        if (lastResp.status === 429 && attempt < maxRetries) {
200	          const waitMs = getRetryAfterMs(lastResp.headers, attempt);
201	          logger.debug(`QuiverAI: rate limited, retry ${attempt + 1}/${maxRetries} in ${waitMs}ms`);
202	          await lastResp.body?.cancel();
203	          await new Promise((resolve) => setTimeout(resolve, waitMs));
204	          continue;
205	        }
206	
207	        if (!lastResp.ok) {
208	          return await handleStreamingError(lastResp);
209	        }
210	
211	        if (!lastResp.body) {
212	          return { error: 'QuiverAI streaming response has no body' };
213	        }
214	
215	        reader = lastResp.body.getReader();
216	        return await readSSEStream(reader);
217	      } finally {
218	        reader?.cancel().catch(() => {});
219	        clearTimeout(timeout);
220	      }
221	    }
222	
223	    // All retries exhausted — return the last error as a normal error response
224	    return handleStreamingError(lastResp!);
225	  }
226	}
