47	/**
48	 * Normalize audio format to proper MIME type.
49	 * Some providers return just 'wav' instead of 'audio/wav'.
50	 * @internal Exported for testing
51	 */
52	export function normalizeAudioMimeType(format: string | undefined): string {
53	  if (!format) {
54	    return 'audio/wav';
55	  }
56	
57	  const trimmedFormat = format.trim();
58	
59	  // Already a proper audio MIME type - validate strictly to prevent MIME injection
60	  // Only allow: audio/subtype where subtype is alphanumeric with optional dash/underscore/plus
61	  // Periods are NOT allowed to prevent attacks like "audio/wav.html" being interpreted as HTML
62	  if (/^audio\/[a-z0-9_+-]+$/i.test(trimmedFormat)) {
63	    return trimmedFormat;
64	  }
65	
66	  // Normalize common formats (e.g., "wav", "mp3")
67	  const formatLower = trimmedFormat.toLowerCase();
68	  const mimeMap: Record<string, string> = {
69	    wav: 'audio/wav',
70	    mp3: 'audio/mpeg',
71	    ogg: 'audio/ogg',
72	    flac: 'audio/flac',
73	    aac: 'audio/aac',
74	    m4a: 'audio/mp4',
75	    webm: 'audio/webm',
76	  };
77	
78	  // Check if format is in the known map
79	  if (mimeMap[formatLower]) {
80	    return mimeMap[formatLower];
81	  }
82	
83	  // Validate format contains only alphanumeric, dash, or underscore
84	  // Periods are NOT allowed to prevent MIME injection attacks (e.g., "wav.html" -> "audio/wav.html")
85	  // which browsers could interpret as HTML and execute embedded scripts
86	  if (!/^[a-z0-9_-]+$/i.test(formatLower)) {
87	    logger.warn('[BlobExtractor] Invalid audio format, using default', { format });
88	    return 'audio/wav';
89	  }
90	
91	  return `audio/${formatLower}`;
92	}
