51	// Helper to create a readable stream from SSE text, optionally split into chunks
52	function createSSEStream(events: string, splitAt?: number[]) {
53	  const encoder = new TextEncoder();
54	  return new ReadableStream({
55	    start(controller) {
56	      if (splitAt?.length) {
57	        let prev = 0;
58	        for (const idx of splitAt) {
59	          controller.enqueue(encoder.encode(events.slice(prev, idx)));
60	          prev = idx;
61	        }
62	        if (prev < events.length) {
63	          controller.enqueue(encoder.encode(events.slice(prev)));
64	        }
65	      } else {
66	        controller.enqueue(encoder.encode(events));
67	      }
68	      controller.close();
69	    },
70	  });
71	}
