19	let defaultProvider: BlobStorageProvider | null = null;
20	
21	function createDefaultProvider(): BlobStorageProvider {
22	  // OSS: filesystem-only media storage. Cloud/on-prem can override by calling setBlobStorageProvider().
23	  return new FilesystemBlobStorageProvider();
24	}
