26	export function getBlobStorageProvider(): BlobStorageProvider {
27	  if (!defaultProvider) {
28	    defaultProvider = createDefaultProvider();
29	    logger.debug('[BlobStorage] Initialized provider', { provider: defaultProvider.providerId });
30	  }
31	  return defaultProvider;
32	}
