43	export async function storeBlob(
44	  data: Buffer,
45	  mimeType: string,
46	  refContext?: {
47	    evalId?: string;
48	    testIdx?: number;
49	    promptIdx?: number;
50	    location?: string;
51	    kind?: string;
52	  },
53	): Promise<BlobStoreResult> {
54	  const provider = getBlobStorageProvider();
55	  const result = await provider.store(data, mimeType);
56	
57	  // Track asset and reference in DB for dedup/auth/cascade
58	  const db = getDb();
59	  try {
60	    db.transaction(() => {
61	      const assetInsert = db
62	        .insert(blobAssetsTable)
63	        .values({
64	          hash: result.ref.hash,
65	          sizeBytes: result.ref.sizeBytes,
66	          mimeType: result.ref.mimeType,
67	          provider: result.ref.provider,
68	        })
69	        .onConflictDoNothing()
70	        .run();
71	
72	      const refInsert =
73	        refContext?.evalId &&
74	        db
75	          .insert(blobReferencesTable)
76	          .values({
77	            id: randomUUID(),
78	            blobHash: result.ref.hash,
79	            evalId: refContext.evalId,
80	            testIdx: refContext.testIdx,
81	            promptIdx: refContext.promptIdx,
82	            location: refContext.location,
83	            kind: refContext.kind,
84	          })
85	          .onConflictDoNothing()
86	          .run();
87	
88	      // Return a non-undefined value to satisfy Drizzle's sync transaction semantics
89	      return refInsert ?? assetInsert;
90	    });
91	  } catch (error) {
92	    // Roll back filesystem write if DB persistence fails
93	    try {
94	      await provider.deleteByHash(result.ref.hash);
95	    } catch (cleanupError) {
96	      logger.warn('[BlobStorage] Failed to rollback blob after DB error', {
97	        error: cleanupError,
98	        hash: result.ref.hash,
99	      });
100	    }
101	    throw error;
102	  }
103	
104	  return result;
105	}
