117	export async function recordBlobReference(
118	  hash: string,
119	  refContext: {
120	    evalId?: string;
121	    testIdx?: number;
122	    promptIdx?: number;
123	    location?: string;
124	    kind?: string;
125	  },
126	): Promise<void> {
127	  if (!refContext.evalId) {
128	    return;
129	  }
130	
131	  const provider = getBlobStorageProvider();
132	  const exists = await provider.exists(hash).catch(() => false);
133	  if (!exists) {
134	    logger.debug('[BlobStorage] Attempted to record reference for missing blob', {
135	      hash,
136	      evalId: refContext.evalId,
137	      location: refContext.location,
138	    });
139	    return;
140	  }
141	
142	  const db = getDb();
143	  const existing = db
144	    .select({ id: blobReferencesTable.id })
145	    .from(blobReferencesTable)
146	    .where(
147	      and(
148	        eq(blobReferencesTable.blobHash, hash),
149	        eq(blobReferencesTable.evalId, refContext.evalId),
150	      ),
151	    )
152	    .get();
153	
154	  if (existing) {
155	    return;
156	  }
157	
158	  db.insert(blobReferencesTable)
159	    .values({
160	      id: randomUUID(),
161	      blobHash: hash,
162	      evalId: refContext.evalId,
163	      testIdx: refContext.testIdx,
164	      promptIdx: refContext.promptIdx,
165	      location: refContext.location,
166	      kind: refContext.kind,
167	    })
168	    .run();
169	}
